    struct OurFire
    {
        std::uint32_t start = 0;
        void* fire = nullptr;
        bool alive = false;
        // After a jump: the ground state at restoreMs is written on the
        // fire's area item once the engine made it; endAfter: the fire had
        // ended by then and is shut down right after the write.
        bool restore = false;
        bool endAfter = false;
        bool stopped = false; // its recorded stop was played
        std::uint8_t endInstant = 0;
        std::uint8_t endArg3 = 0;
        std::uint32_t restoreMs = 0;
        ULONGLONG restoreSince = 0;
        // The slot generation of this start; every write into the CFire goes
        // through WriteOurFire with it.
        std::uint32_t generation = 0;
        // The world's own fire that is this initial start (kept by the
        // clip-aware clear, not lit again); keep: survives the next
        // ClearPoseV2Fires (a rebuild that still wants it burning, the end
        // of the playback that gives it back).
        bool adopted = false;
        bool keep = false;
    };
    std::uint64_t g_poseV2FireStateRefused = 0;

    // Age and seed writes through the guarded helper (pool, generation of
    // our start, known field, SEH); a refusal is counted and the first ones
    // logged, the fire is left as the engine has it.
    bool WriteOurFire(const OurFire& ours, std::size_t offset, const void* data, std::size_t size)
    {
        // An adopted fire the detours never saw start has no generation: the
        // world's state is left as it is.
        if (ours.adopted && !ours.generation)
            return false;
        std::string error;
        if (replay::fire::WriteFireState(ours.fire, ours.generation, offset, data, size, error))
            return true;
        if (++g_poseV2FireStateRefused <= 8)
            Ctx().log << "POSE_V2_FIRE_STATE_REFUSED,start=" << ours.start << ",offset=0x" << std::hex << offset
                      << std::dec << ",error=" << error << '\n';
        return false;
    }
