    struct FxOwned
    {
        std::uint64_t owner = 0;
        std::uint64_t inst = 0;
        std::uint32_t hash = 0;
        std::uint32_t lastFlags2 = 0;   // after the last end-of-tick clear
        bool lastKnown = false;
        Entity handle = 0;              // the owner's handle (its position at the end of the tick)
    };
    std::vector<FxOwned> g_fxOwned;
    // FxRelocateClearStill: the owners' positions at the end of the last
    // tick (an owner the playback did not place this tick is cleared by its
    // own step), the counters and the probe FX_RELOCATE_UNPLACED (capped per
    // hash).
    struct FxOwnerAt
    {
        float at[3] = {};
        std::uint64_t tick = 0;
    };
    std::unordered_map<std::uint64_t, FxOwnerAt> g_fxOwnerLastAt;
    std::uint64_t g_fxEndTick = 0;
    std::uint64_t g_fxRelocateClearedStill = 0, g_fxRelocateKeptUnplaced = 0;
    std::uint32_t g_fxUnplacedLogs = 0;
    std::map<std::uint32_t, std::uint32_t> g_fxUnplacedLogsByHash;
    std::vector<std::pair<std::uint64_t, float>> g_fxPlacedThisTick;
    struct FxProbeBefore
    {
        std::uint64_t inst = 0;
        std::uint32_t before = 0;
        std::uint32_t prevTick = 0;
        bool prevKnown = false;
    };
    std::vector<FxProbeBefore> g_fxProbeBefore;
    std::uint64_t g_fxNextVeladdWallMs = 0;
    std::uint64_t g_fxNextRecVeladdWallMs = 0;
    // Our one-shots checked one tick after their start.
    struct FxPendingCheck
    {
        std::uint64_t inst = 0;
        std::uint32_t hash = 0;
        std::uint32_t site = 0;
        std::uint64_t entity = 0;     // attached: the puppet it rides
        float expected[3] = {};       // world: the recorded place
        bool weapon = false;
        bool hasSettings = false;
        replay::entity::FxSettings settings;
        std::uint32_t ticks = 0;
    };
    std::vector<FxPendingCheck> g_fxPendingChecks;
    // The shot track's weapon effects.
    bool g_fxClipWeaponEvents = false;
    std::vector<replay::shotfx::Decision> g_fxShotDecisions;
    replay::shotfx::Audit g_fxShotAudit;
    std::uint32_t g_fxImpactOnBodyLogs = 0;
    std::uint64_t g_fxShotResolveShots = 0, g_fxShotMuzzleStarts = 0, g_fxShotImpactStarts = 0, g_fxShotBodyStarts = 0;
    std::uint64_t g_fxShotClaimedMulti = 0, g_fxShotNoMuzzle = 0, g_fxShotClaimed = 0;
    std::map<std::uint64_t, std::uint32_t> g_fxShotTriggerClaims; // trigger (time ^ hash) -> shots that took it
    std::uint32_t g_fxShotFxLogs = 0;
    std::uint32_t g_poseV2RegisteredPrevTickMs = 0; // the recording's previous tick
    bool IsWeaponFxSite(std::uint32_t site)
    {
        return site == replay::fx::kMuzzleFlashSite || site == replay::fx::kBulletImpactSite || site == replay::shotfx::kBodySite ||
            site == 0x146098D || site == 0x1467AEC;
    }
    // Why a registered track was not created (the last reason seen), for
    // the tracks the playback never created: the fx check's missing rows.
    enum class RegNotCreated : std::uint8_t { None, Created, FireSite, CameraAmbient, Paused, OwnerMissing, OwnerMismatch, OwnerNotReady, WeaponIntent };
    std::vector<RegNotCreated> g_fxRegReason;
    std::uint64_t g_fxRegRecreated = 0; // our registered instances made again for a track already created
    std::uint32_t g_fxCheckReachedMs = 0; // the furthest playhead of this playback (clip basis counts up to it)
    std::uint64_t g_fxPassedNotNormal = 0; // one-shots the playhead passed outside normal play
    // The clip time this playback traversed in normal play (merged spans):
    // the clip basis counts the events inside them (a clip started at its
    // in-point jumps over the start).
    std::vector<std::pair<std::uint32_t, std::uint32_t>> g_fxCheckSpans;
    std::uint32_t g_fxCheckLastMs = 0;
    std::uint32_t g_fxPassedLogs = 0;
    void NoteRegReason(std::size_t index, RegNotCreated reason)
    {
        if (index >= g_fxRegReason.size())
            g_fxRegReason.resize(index + 1, RegNotCreated::None);
        if (g_fxRegReason[index] != RegNotCreated::Created)
            g_fxRegReason[index] = reason;
    }
    std::uint32_t g_fxOwnLastPlayhead = 0;
    std::uint64_t g_fxOwnOneShotsCleared = 0;
    std::uint64_t g_fxOwnOneShotsClears = 0;

    // The families with their own tracks that the owner rule never touches
    // (blood, explosion, fire, gore; the weapon sites are checked by site in
    // the observer): names from the public femga list.
    constexpr std::uint32_t FxJoaat(const char* text)
    {
        std::uint32_t hash = 0;
        for (; *text; ++text)
        {
            const char c = (*text >= 'A' && *text <= 'Z') ? static_cast<char>(*text - 'A' + 'a') : *text;
            hash += static_cast<std::uint8_t>(c);
            hash += hash << 10;
            hash ^= hash >> 6;
        }
        hash += hash << 3;
        hash ^= hash >> 11;
        hash += hash << 15;
        return hash;
    }
    std::vector<std::uint32_t> FxOwnerExemptHashes()
    {
        static const char* const kNames[] = {
            "blood_entry", "blood_entry_critical", "blood_exit", "blood_exit_critical", "blood_mist", "blood_melee_punch",
            "blood_melee_blunt", "blood_melee_slash", "blood_stab", "blood_headshot", "blood_wheel", "blood_animal",
            "exp_grd_dynamite", "exp_air_dynamite", "exp_air_firebottle", "exp_grd_firebottle", "exp_grd_molotov",
            "fire_spread_generic", "fire_spread_generic_obj", "fire_spread_generic_smoulder_loop", "fire_ped_body",
            "fire_ped_limb", "bullet_tracer", "bullet_tracer_incendiary", "bullet_shotgun_tracer",
        };
        std::vector<std::uint32_t> out;
        for (const char* name : kNames)
            out.push_back(FxJoaat(name));
        out.push_back(0x45FAF2C0u); // the bleeding (registered)
        return out;
    }

    void LogPoseV2FxHistogram(const char* phase)
    {
        std::vector<replay::fx::TriggerCall> calls;
        replay::fx::Collect(g_poseV2FxPhaseStartUs, replay::fx::NowUs(), calls);
        std::map<std::uint32_t, std::pair<std::uint32_t, std::uint32_t>> histogram; // calls, instances
        for (const replay::fx::TriggerCall& call : calls)
        {
            std::pair<std::uint32_t, std::uint32_t>& entry = histogram[call.effectHash];
            ++entry.first;
            if (call.instance)
                ++entry.second;
        }
        std::vector<std::pair<std::uint32_t, std::pair<std::uint32_t, std::uint32_t>>> sorted(
            histogram.begin(), histogram.end());
        std::sort(sorted.begin(), sorted.end(),
            [](const auto& a, const auto& b) { return a.second.first > b.second.first; });
        std::ostream& log = Ctx().log;
        log << "POSE_V2_FX_HISTOGRAM,phase=" << phase << ",calls=" << calls.size()
            << ",effects=" << histogram.size() << ",top=";
        std::size_t shown = 0;
        for (const auto& entry : sorted)
        {
            if (shown++ == 24)
                break;
            log << (shown > 1 ? ";" : "") << "0x" << std::hex << entry.first << std::dec << ":"
                << entry.second.first << "/" << entry.second.second;
        }
        log << '\n';
        log.flush();
    }
    bool g_poseV2FxPlayerReady = false;
    constexpr std::uint64_t kPoseV2FxBeforeUs = 100000;
    constexpr std::uint64_t kPoseV2FxAfterUs = 100000;

    // Playback side of the shot events.
    replay::entity::ForwardEventCursor g_poseV2SpeechCursorPlay;
    std::uint64_t g_poseV2SpeechPlayed = 0;

    // A queued line (recorded or replayed), followed every frame until it
    // leaves the speaker's line list: how long it lived, its states and why
    // it was stopped.
    struct PoseV2QueuedLine
    {
        Ped ped = 0;
        replay::entity::ReplayId id;
        std::uint64_t line = 0;
        std::uint64_t queuedUs = 0;
        std::uint32_t context = 0;
        std::uint32_t frames = 0;
        const char* phase = "playback";
        // Line state (+0x234) each time it changed, as "frame:state".
        std::string states;
        std::int32_t lastState = -2;
    };
    std::vector<PoseV2QueuedLine> g_poseV2QueuedLines;
    int g_poseV2QueuedLineBudget = 0;
    std::uint64_t g_poseV2CoreCursor = 0;
    std::uint64_t g_poseV2SpeechCancelled = 0;
    replay::entity::ForwardEventCursor g_poseV2ShotCursor;
    std::uint64_t g_poseV2ShotsPlayed = 0;
    std::uint64_t g_poseV2ShotsCancelled = 0;

    replay::pose::Vec3 ToPoseVec(const Vector3& v)
    {
        return {v.x, v.y, v.z};
    }

    // The gunshot's start after its fire event, per shooter, recorded and
    // replayed (shot_audio_delay.h). A fire (the game's in the recording,
    // the replay's EnqueueFire in the playback) is matched with the census
    // row of the sound created on its weapon's audio (CWeapon +0x100, the
    // event's +0x00), the bank of that sound's ref is probed, and the
    // sound's play state is read every tick until it plays.
    // RedemptionEditor.ini ShotAudioDelay (default 1; 0: nothing of this
    // runs). Read only (guarded reads, the game's own bank lookups); nothing
    // in the world changes, so nothing to restore.
    replay::shotdelay::Tracker g_shotDelay;
    const char* g_shotDelayPhase = "rec";
    bool g_shotDelayOn = false;
    int g_shotDelayShotLines = 0;
    constexpr int kShotDelayShotLines = 40; // POSE_V2_SHOT_AUDIO_DELAY_SHOT lines per phase
    constexpr std::size_t kWeaponAudioInCWeapon = 0x100;
    std::vector<replay::shotdelay::Create> g_shotDelayRows;
    std::vector<std::size_t> g_shotDelayIndexes;

    void BeginShotAudioDelay(const char* phase)
    {
        char directory[MAX_PATH]{};
        GetCurrentDirectoryA(MAX_PATH, directory);
        const std::string ini = replay::identity::IniPathIn(directory);
        g_shotDelayOn = replay::identity::DevIniInt("ShotAudioDelay", 1, ini.c_str()) != 0;
        g_shotDelay.Reset();
        g_shotDelayPhase = phase;
        g_shotDelayShotLines = 0;
    }

    // The listener's distance: the rendered camera to the muzzle.
    float ShotAudioDistance(const replay::pose::Vec3& muzzle)
    {
        const Vector3 camera = CAM::GET_FINAL_RENDERED_CAM_COORD();
        const float dx = camera.x - muzzle.x;
        const float dy = camera.y - muzzle.y;
        const float dz = camera.z - muzzle.z;
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }

    void NoteShotAudioFire(const replay::entity::ReplayId& shooter, const std::uint8_t* info, std::uint64_t fireUs,
        std::uint32_t eventMs, const replay::pose::Vec3& muzzle, bool player)
    {
        if (!g_shotDelayOn || !info)
            return;
        std::uint64_t cweapon = 0;
        std::memcpy(&cweapon, info, 8);
        if (!cweapon)
            return;
        replay::shotdelay::Fire fire;
        fire.shooter = shooter.Packed();
        fire.audio = cweapon + kWeaponAudioInCWeapon;
        fire.fireUs = fireUs;
        fire.eventMs = eventMs;
        fire.distanceM = ShotAudioDistance(muzzle);
        fire.player = player; // POSE_V2_SHOT_PLAYER_BANK
        g_shotDelay.AddFire(fire);
    }

    void LogShotAudioDelayFinished()
    {
        for (const replay::shotdelay::Shot& shot : g_shotDelay.TakeFinished())
        {
            if (g_shotDelayShotLines >= kShotDelayShotLines)
                break;
            ++g_shotDelayShotLines;
            Ctx().log << replay::shotdelay::ShotLine(g_shotDelayPhase, shot,
                replay::entity::IdText(replay::entity::ReplayId::FromPacked(shot.fire.shooter)));
        }
    }

    // Every recording or playback tick, after the shots of the tick (the
    // census rows of this tick are still in census::Rows()).
    void TickShotAudioDelay()
    {
        if (!g_shotDelayOn || !g_shotDelay.Size())
            return;
        REPLAY_PROFILE_ZONE("shots.audio_delay");
        g_shotDelayRows.clear();
        for (const replay::census::TickRow& tick : replay::census::Rows())
        {
            replay::shotdelay::Create create;
            create.timeUs = tick.row.timeUs;
            create.audio = tick.row.audio;
            create.sound = tick.row.sound;
            create.ref = tick.row.ref;
            create.firePath = replay::shotdelay::InFirePlay(tick.row.callers, replay::census::kRowCallers);
            g_shotDelayRows.push_back(create);
        }
        g_shotDelay.OnCreates(g_shotDelayRows, g_shotDelayIndexes);
        for (const std::size_t index : g_shotDelayIndexes)
        {
            replay::shotdelay::Shot& shot = g_shotDelay.At(index);
            shot.identity = replay::audio::SoundIdentity(shot.sound);
            replay::audio::BankProbe bank;
            std::string error;
            if (shot.ref && replay::audio::ProbeSoundBank(shot.ref, bank, error))
                shot.bank = replay::shotdelay::BankOfName(replay::audio::BankStateName(bank));
        }
        g_shotDelay.Waiting(g_shotDelayIndexes);
        const std::uint64_t nowUs = replay::clock::NowUs();
        for (const std::size_t index : g_shotDelayIndexes)
        {
            replay::shotdelay::Shot& shot = g_shotDelay.At(index);
            int state = -1;
            const bool alive = replay::audio::SoundPlayState(shot.sound, shot.identity, state);
            g_shotDelay.Sample(index, alive, state, nowUs);
        }
        g_shotDelay.Expire(nowUs);
        LogShotAudioDelayFinished();
    }

    // The phase's end: everything still open closes, then the summary
    // (`refs`: the clip's reference, playback only).
    void EndShotAudioDelay(const std::map<std::uint32_t, replay::shotdelay::Reference>* refs)
    {
        if (!g_shotDelayOn)
            return;
        g_shotDelay.Expire(replay::clock::NowUs(), true);
        LogShotAudioDelayFinished();
        Ctx().log << replay::shotdelay::SummaryLines(g_shotDelayPhase, g_shotDelay.Tallies(), refs,
            [](std::uint32_t id) { return replay::entity::IdText(replay::entity::ReplayId::FromPacked(id)); });
        g_shotDelay.Reset();
        g_shotDelayOn = false;
    }

    // The recording's own gunshot creates of the clip (SGEN), per shooter,
    // against the shots' recorded ticks: the baseline a clip carries.
    std::map<std::uint32_t, replay::shotdelay::Reference> ShotAudioClipReference()
    {
        std::vector<replay::shotdelay::RefShot> shots;
        for (const replay::entity::ShotEvent& shot : Ctx().clip.shots.Shots())
            if (shot.weapon.Valid())
                shots.push_back({shot.shooter.Packed(), shot.weapon.Packed(), shot.timeMs});
        std::vector<replay::shotdelay::RefPacket> packets;
        for (const replay::soundgeneric::CreatePacket& c : Ctx().clip.soundGeneric.creates)
        {
            const bool weapon = c.audioKnown && c.audioBase == replay::census::AudioBase::WeaponAudio;
            if (weapon)
                packets.push_back({c.owner, c.timeMs, true, replay::shotdelay::InFirePlay(&c.caller, 1) || replay::shotdelay::InFirePlay(c.path, 3)});
        }
        std::stable_sort(packets.begin(), packets.end(),
            [](const replay::shotdelay::RefPacket& a, const replay::shotdelay::RefPacket& b) { return a.timeMs < b.timeMs; });
        return replay::shotdelay::ClipReference(shots, packets);
    }

    // `hand`: the weapon attach point that fired (0 primary, 1 secondary
    // when dual wielding); `fire`: the engine fire event of this shot when
    // the shot comes from the fire event queue.
    // Evidence, read only. Per shot, record and play: the shooter's gunfight
    // offsets that 0x2EF8120 adds to the shot (volume, high-pass) and the
    // audio flags dword [0x5B9CFC0].
    void LogShotGunfight(const char* phase, const replay::entity::ReplayId& shooter, void* ped, std::uint32_t timeMs)
    {
        float volume = 0.0f;
        std::int32_t highPass = 0;
        std::uint32_t flags = 0;
        const bool ok = ped && replay::audio::PedGunfightOffsets(ped, volume, highPass);
        const bool flagsOk = replay::audio::AudioGlobalFlags(flags);
        Ctx().log << "SHOT_GUNFIGHT,phase=" << phase << ",shooter=" << replay::entity::IdText(shooter) << ",time_ms=" << timeMs
                  << ",ok=" << (ok ? 1 : 0) << ",vol=" << volume << ",hpf=" << highPass << ",flags_ok=" << (flagsOk ? 1 : 0)
                  << ",flags=0x" << std::hex << flags << std::dec << ",bit2=" << ((flags >> 2) & 1) << ",bit3=" << ((flags >> 3) & 1)
                  << ",bit4=" << ((flags >> 4) & 1) << ",bit5=" << ((flags >> 5) & 1) << '\n';
    }

    void RecordPoseV2Shot(const replay::recorder::RecordedEntity& owner, PoseV2ShooterState& state, const char* source,
        int hand = 0, const replay::audio::FireCall* fire = nullptr)
    {
        replay::entity::ShotEvent shot;
        shot.timeMs = replay::pose::capture::NowMs();
        shot.shooter = owner.id;
        shot.weaponHash = state.weapon;
        Hash handWeapon = 0;
        if (hand != 0 && WEAPON::GET_CURRENT_PED_WEAPON(owner.handle, &handWeapon, FALSE, hand, FALSE) && handWeapon)
            shot.weaponHash = handWeapon;
        const Entity object = WEAPON::GET_CURRENT_PED_WEAPON_ENTITY_INDEX(owner.handle, hand);
        bool muzzleBone = false;
        if (object && replay::entities::Exists(object))
        {
            for (const replay::recorder::RecordedWeapon& weapon : Ctx().recorder.weapons)
            {
                if (weapon.object == object)
                    shot.weapon = weapon.id;
            }
            Vector3 muzzle{};
            muzzleBone = replay::pose::playback::WeaponMuzzle(object, muzzle);
            if (!muzzleBone)
                muzzle = ENTITY::GET_ENTITY_COORDS(object, TRUE, FALSE);
            shot.muzzle = ToPoseVec(muzzle);
            const Vector3 origin = ENTITY::GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(object, 0.0f, 0.0f, 0.0f);
            const Vector3 axis = ENTITY::GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(object, 1.0f, 0.0f, 0.0f);
            shot.direction = {axis.x - origin.x, axis.y - origin.y, axis.z - origin.z};
        }
        else
        {
            shot.muzzle = ToPoseVec(PED::GET_PED_BONE_COORDS(owner.handle, 0, 0.0f, 0.0f, 0.0f));
            shot.direction = ToPoseVec(ENTITY::GET_ENTITY_FORWARD_VECTOR(owner.handle));
        }
        // The local player's shots play the player weapon sound (see
        // replay::audio::InstallPlayerWeaponAudio). audio_flag is the
        // engine's own answer for this ped (read-only replica), evidence
        // that the weapon audio took the player variant live.
        shot.shooterPlayer = owner.handle == PLAYER::PLAYER_PED_ID() ? 2 : 1;
        const int audioPlayerFlag = replay::audio::PedAudioPlayerFlag(replay::entities::AddressOf(owner.handle));
        state.pendingEvent = Ctx().clip.shots.Add(shot);
        if (fire) // the game's fire event
            NoteShotAudioFire(shot.shooter, fire->info, fire->timeUs, shot.timeMs, shot.muzzle, shot.shooterPlayer == 2);
        if (g_poseV2FxObserverReady)
        {
            PoseV2FxWindow window;
            window.shot = state.pendingEvent;
            window.shotUs = replay::fx::NowUs();
            BYTE* shooterAddress = replay::entities::AddressOf(owner.handle);
            window.shooter = reinterpret_cast<std::uint64_t>(shooterAddress);
            window.shooterAudio = replay::audio::PedAudio(shooterAddress);
            window.weapon = object && replay::entities::Exists(object)
                ? reinterpret_cast<std::uint64_t>(replay::entities::AddressOf(object))
                : 0;
            if (fire)
            {
                window.fire = *fire;
                window.hasFire = true;
            }
            // The window is part of the shot record: its flush resolves the
            // muzzle and impact effects, the muzzle flags and the fire audio
            // of the shot. Gating it off leaves every shot without muzzle
            // flash and fire audio.
            g_poseV2FxWindows.push_back(window);
        }
        OpenPoseV2AudioWindow("shot:" + std::to_string(state.pendingEvent), 100000, 150000);
        state.pendingImpact = true;
        state.pendingSinceMs = shot.timeMs;

        std::ostream& log = Ctx().log;
        log << "POSE_V2_SHOT"
            << ",shooter=" << replay::entity::IdText(shot.shooter)
            << ",weapon_entity=" << (shot.weapon.Valid() ? replay::entity::IdText(shot.weapon) : std::string("none"))
            << ",weapon=0x" << std::hex << shot.weaponHash << std::dec
            << ",source=" << source
            << ",muzzle_bone=" << (muzzleBone ? 1 : 0)
            << ",shooter_player=" << static_cast<int>(shot.shooterPlayer)
            << ",audio_flag=" << audioPlayerFlag
            << ",clip=" << state.clip
            << ",time_ms=" << shot.timeMs
            << '\n';
        LogShotGunfight("record", shot.shooter, replay::entities::AddressOf(owner.handle), shot.timeMs);
        log.flush();
    }

    // Surface normal at the impact: one read-only ray from the muzzle
    // through the impact point.
    void MeasurePoseV2ImpactNormal(replay::entity::ShotEvent& shot, Ped shooter)
    {
        float dx = shot.impact.x - shot.muzzle.x;
        float dy = shot.impact.y - shot.muzzle.y;
        float dz = shot.impact.z - shot.muzzle.z;
        const float length = std::sqrt(dx * dx + dy * dy + dz * dz);
        if (length < 0.01f)
            return;
        dx /= length;
        dy /= length;
        dz /= length;
        const float startBack = (std::min)(0.5f, length);
        const ScrHandle probe = SHAPETEST::START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE(
            shot.impact.x - dx * startBack, shot.impact.y - dy * startBack, shot.impact.z - dz * startBack,
            shot.impact.x + dx * 0.25f, shot.impact.y + dy * 0.25f, shot.impact.z + dz * 0.25f,
            -1, shooter, 7);
        BOOL hit = FALSE;
        Vector3 end{};
        Vector3 normal{};
        Entity entity = 0;
        if (SHAPETEST::GET_SHAPE_TEST_RESULT(probe, &hit, &end, &normal, &entity) == 2 && hit)
        {
            shot.impactNormal = ToPoseVec(normal);
            shot.hasNormal = true;
        }
    }

    // record=false while the recording gate holds: the engine fire queue is
    // drained and the per-ped baselines (weapon, clip, shooting, last
    // impact) follow the game, but no shot is recorded.
    void RecordPoseV2Shots(bool record = true)
    {
        REPLAY_PROFILE_ZONE("rec.shots");
        const std::uint32_t timeMs = replay::pose::capture::NowMs();
        // With the fire event observer the shots of every hand come from
        // the engine fire queue (a shot is recorded at its fire event).
        g_poseV2FireShotsSource = g_poseV2AudioObserverReady;
        if (g_poseV2FireShotsSource)
            replay::audio::CollectFiresSince(g_poseV2FireCursor, g_poseV2FrameFires);
        g_poseV2Shooters.erase(std::remove_if(g_poseV2Shooters.begin(), g_poseV2Shooters.end(),
            [](const PoseV2ShooterState& state) {
                return std::none_of(Ctx().recorder.entities.begin(), Ctx().recorder.entities.end(),
                    [&](const replay::recorder::RecordedEntity& entity) { return entity.handle == state.ped; });
            }), g_poseV2Shooters.end());
        for (const replay::recorder::RecordedEntity& owner : Ctx().recorder.entities)
        {
            if (owner.vehicle)
                continue;
            auto state = std::find_if(g_poseV2Shooters.begin(), g_poseV2Shooters.end(),
                [&](const PoseV2ShooterState& candidate) { return candidate.ped == owner.handle; });
            const bool known = state != g_poseV2Shooters.end();
            if (!known)
            {
                g_poseV2Shooters.push_back({owner.handle});
                state = g_poseV2Shooters.end() - 1;
            }

            Hash weapon = 0;
            WEAPON::GET_CURRENT_PED_WEAPON(owner.handle, &weapon, FALSE, 0, FALSE);
            int clip = -1;
            if (!WEAPON::GET_AMMO_IN_CLIP(owner.handle, &clip, weapon))
                clip = -1;
            const bool shooting = PED::IS_PED_SHOOTING(owner.handle) != FALSE;
            Vector3 impact{};
            const bool hasImpact = WEAPON::GET_PED_LAST_WEAPON_IMPACT_COORD(owner.handle, &impact) != FALSE;

            // Compared before this frame updates the baseline.
            const bool newImpact = hasImpact && (!state->hasLastImpact ||
                std::fabs(impact.x - state->lastImpact.x) + std::fabs(impact.y - state->lastImpact.y) +
                    std::fabs(impact.z - state->lastImpact.z) > 0.01f);
            int shots = 0;
            const char* source = "none";
            if (known && weapon == state->weapon && clip >= 0 && state->clip >= 0)
            {
                if (clip < state->clip)
                {
                    shots = (std::min)(state->clip - clip, kPoseV2MaxShotsPerFrame);
                    source = "clip";
                }
            }
            else if (known && shooting && !state->shooting)
            {
                shots = 1;
                source = "edge";
            }
            state->weapon = weapon;
            state->clip = clip;
            state->shooting = shooting;
            if (hasImpact)
            {
                state->lastImpact = impact;
                state->hasLastImpact = true;
            }
            if (!record)
            {
                state->pendingImpact = false;
                continue;
            }
            if (g_poseV2FireShotsSource)
            {
                // Shots come from the engine fire events (either hand); the
                // clip only keeps the impact bookkeeping above.
                shots = 0;
                const std::uint64_t address = reinterpret_cast<std::uint64_t>(replay::entities::AddressOf(owner.handle));
                for (const replay::audio::FireCall& fire : g_poseV2FrameFires)
                {
                    std::uint64_t shooterRef = 0;
                    std::memcpy(&shooterRef, fire.info + 0x10, 8);
                    if (!address || shooterRef != address)
                        continue;
                    // Which hand's weapon object holds the event's weapon
                    // reference (+0x00)?
                    std::uint64_t weaponRef = 0;
                    std::memcpy(&weaponRef, fire.info, 8);
                    int hand = 0;
                    for (int point = 0; point < 2 && weaponRef; ++point)
                    {
                        const Entity object = WEAPON::GET_CURRENT_PED_WEAPON_ENTITY_INDEX(owner.handle, point);
                        if (!object || !replay::entities::Exists(object))
                            continue;
                        static std::uint64_t words[0x200];
                        if (!replay::audio::ReadBytes(reinterpret_cast<std::uint64_t>(replay::entities::AddressOf(object)),
                                words, sizeof(words)))
                        {
                            continue;
                        }
                        if (std::find(std::begin(words), std::end(words), weaponRef) != std::end(words))
                        {
                            hand = point;
                            break;
                        }
                    }
                    RecordPoseV2Shot(owner, *state, hand ? "fire_event_left" : "fire_event", hand, &fire);
                }
            }
            for (int shot = 0; shot < shots; ++shot)
                RecordPoseV2Shot(owner, *state, source);
            // A new impact coordinate (same frame or shortly after) belongs
            // to the latest shot.
            if (state->pendingImpact)
            {
                if (newImpact && known)
                {
                    replay::entity::ShotEvent& shot = Ctx().clip.shots.At(state->pendingEvent);
                    shot.impact = ToPoseVec(impact);
                    shot.hasImpact = true;
                    MeasurePoseV2ImpactNormal(shot, owner.handle);
                    state->pendingImpact = false;
                    ++g_poseV2ShotImpacts;
                }
                else if (timeMs - state->pendingSinceMs > kPoseV2ImpactWindowMs)
                {
                    state->pendingImpact = false;
                }
            }
        }
    }

